/** Long-form companions to STORIES, keyed by the story's title. Drafts until reviewed (reviews.ts). */
import type { Depth } from "./depth-types.js";
export const DEPTH_STORIES: Record<string, Depth> = {
"Adam and the first mistake": { sections: [
  { h: "The story", p: [
    "Before Adam was made, Allah told the angels that He would place a vicegerent on the earth. The angels asked whether He would put there one who would spread corruption and shed blood, while they glorified and sanctified Him. Allah answered that He knew what they did not know. He then taught Adam the names of all things and set them before the angels, who could not name them; Adam could. The angels bowed when commanded. Iblis, who was among them though he was of the jinn, refused. His reason was a comparison: You created me from fire and him from clay. He was expelled, and he asked for respite until the Day people are raised, promising to sit in wait for them on the straight path.",
    "Adam and his wife were settled in the Garden and told to eat freely from wherever they wished, but not to approach one tree, lest they be among the wrongdoers. Satan whispered to them both, swearing that he was a sincere adviser, and told them the tree would make them angels or immortal. They ate. Their nakedness became apparent to them and they began to cover themselves with leaves of the Garden. Their Lord called to them: did I not forbid you that tree and tell you that Satan is a plain enemy to you?",
    "Their answer is the centre of the story. They said: Our Lord, we have wronged ourselves, and if You do not forgive us and have mercy on us we will surely be among the losers. Al-Baqarah adds that Adam received words from his Lord, and He turned to him in forgiveness. They were sent down to the earth, which was always going to be their home, with the promise that guidance would come and that whoever followed it would have nothing to fear.",
    "Two creatures disobeyed in this story. One argued and blamed Allah: because You have led me astray. The other said: we have wronged ourselves. The difference between them is the whole of the story." ] },
  { h: "Where it is in the Quran", l: [
    "2:30–39: the announcement to the angels, the names, the bowing, the tree and the words of repentance.",
    "7:11–25: the fullest account of the whispering and the covering with leaves, with Iblis's argument and his request for respite.",
    "20:115–123: Adam forgot, and We did not find in him firm resolve; the promise of guidance after the descent.",
    "15:26–44 and 38:71–85: Iblis's refusal and his oath to mislead all but the sincere servants.",
    "17:61–65: Satan's threat and the limit on his power: over My servants you have no authority." ] },
  { h: "Al-Mizan's reading", p: [
    "Tabataba'i reads the Garden episode as the human being's first lesson rather than its first crime. The prohibition was not a legal command of the kind that later law brought, because there was no law yet; it was guidance, and crossing it brought its natural result, the loss of ease, not a legal penalty. He points to the Quran's own words: Adam forgot. The earth was the destination from the start, since the announcement to the angels said a vicegerent on the earth before the Garden is mentioned.",
    "He notes that the words of repentance were given to Adam, not invented by him: a human cannot find the way back on his own, and Allah teaches even the form of the apology. The story is thus the pattern of all later guidance: a slip, a turning, and a Lord who turns first." ] },
  { h: "Lessons", l: [
    "The sin that was not forgiven was pride, not the eating. Iblis never admitted anything.",
    "An apology has a form: naming the wrong, asking for mercy, and not shifting blame. The Quran gives it in one sentence.",
    "Knowledge, the names, is what made the human worth bowing to. Learning is part of being human, not an extra.",
    "Satan's first weapon was an oath that he was a sincere adviser. Flattery still arrives dressed as advice." ] },
  { h: "Talk about it", l: [
    "What is the difference between an excuse and an apology? Give one example of each from this week.",
    "Iblis compared fire and clay. When do we compare ourselves to others to avoid doing what is right?",
    "What were the names Adam learned? What does it mean that the first gift was knowledge?" ] } ],
  kids: [ "A long time ago Allah made the first man, Adam, and taught him the names of everything. The angels bowed to him because Allah said so. One of them, Iblis, said: no, I am better than him, I am made of fire and he is made of mud. Allah sent Iblis away because he was proud.",
    "Adam and his wife lived in a beautiful garden. Allah said: eat anything you like, just not from that one tree. Iblis whispered to them: that tree will make you live forever. They listened and ate from it. Straight away they felt terrible.",
    "But Adam did not make excuses. He said: Allah, we did wrong, please forgive us. And Allah forgave him and taught him the right words to say sorry. Iblis never said sorry. So who was the brave one?" ] },

"Nuh and the long patience": { sections: [
  { h: "The story", p: [
    "Nuh was sent to a people who had made idols of righteous men from earlier generations, Wadd, Suwa', Yaghuth, Ya'uq and Nasr, and who worshipped them. Surah Nuh is his own report to his Lord: I called my people night and day, but my calling only made them flee further. Whenever I called them so that You might forgive them, they put their fingers in their ears and covered themselves with their garments, persisted and grew arrogant. He tried every register: openly, then privately, then both. He offered them the simplest promise in the Quran: ask your Lord's forgiveness, He is ever forgiving; He will send the sky upon you in showers, support you with wealth and children, and give you gardens and rivers.",
    "They answered with the oldest objection: you are only a man like us, and only the lowest of us follow you. The nobles demanded that he drive away the poor believers. He refused: I will not drive away those who believe. After nine hundred and fifty years, Allah told him that none would believe except those who already had, and commanded him to build the ark under His eyes and inspiration. He built it on dry land. Every time a group of his people passed by, they mocked him. He said: if you mock us, we will mock you as you mock, and you will know on whom a punishment comes.",
    "When the oven gushed, the sign came. He loaded two of every kind, his family except those already judged, and the believers, who were few. The ark moved on waves like mountains. Nuh called to his son, who stood apart: my son, ride with us, do not be with the disbelievers. The son said: I will take refuge on a mountain. Nuh answered: there is no refuge today from Allah's command except for whom He has mercy on. A wave came between them.",
    "Afterward Nuh prayed: my Lord, my son is of my family, and Your promise is true. The reply is one of the Quran's hardest and clearest sentences: he is not of your family; he is a deed that was not righteous. Nuh asked refuge from asking what he did not know, and was told to disembark with peace and blessings." ] },
  { h: "Where it is in the Quran", l: [
    "71:1–28: Nuh's own account of the call and his final prayer.",
    "11:25–49: the fullest narrative, with the building, the mockery, the son, and the verse that family is a deed.",
    "7:59–64, 10:71–73, 23:23–30, 26:105–122: the call and the refusal told in the pattern of the messengers.",
    "54:9–17: the ark of planks and nails, and the refrain that the Quran is made easy to remember.",
    "29:14: the figure of a thousand years less fifty." ] },
  { h: "Al-Mizan's reading", p: [
    "Tabataba'i treats Nuh as the first of the messengers with a law and a book, and reads the length of his mission as the Quran's proof that guidance does not depend on results: a prophet is responsible for the call, not for the acceptance. He gives weight to the sentence about the son. Kinship in the Quran's sight is a relation of faith and deed, so a son who chose the mountain over the ark had left the family before the wave reached him.",
    "He also reads the promise of rain, wealth and children in Surah Nuh as a general law and not a favour for one nation: seeking forgiveness opens provision, because provision is withheld by sin, a theme he links to 7:96 on the towns that believed." ] },
  { h: "Lessons", l: [
    "Patience has a length the Quran gives in numbers so that no one may say their own effort has gone on too long.",
    "Mockery is a stage, not a verdict. Nuh kept working on the ark in front of the people who laughed.",
    "A family is a shared direction before it is a shared blood. The ark was the family that day.",
    "Nuh did not drive away the poor to win the rich. The condition of the nobles was refused at the cost of the mission's success." ] },
  { h: "Talk about it", l: [
    "What would you keep doing for a year without anyone agreeing with you? For ten years?",
    "Why did Nuh refuse to send the poor believers away, when it might have won the rich?",
    "What does it mean that the son was 'a deed that was not righteous'?" ] } ],
  kids: [ "Nuh was a prophet who told his people to worship only Allah. He told them in the day and in the night, loudly and quietly, for hundreds of years. Most of them laughed at him and put their fingers in their ears.",
    "Allah told Nuh to build a huge ship, far from the sea. People walked past and laughed: a ship on dry land! Nuh kept building. Then the rain came and the water rose everywhere.",
    "Nuh, his family and all the believers were safe in the ship, with two of every animal. Nuh's own son would not get in, and the water took him. The people who listened were the ones who were saved." ] },

"Ibrahim and the idols": { sections: [
  { h: "The story", p: [
    "Ibrahim grew up in a city of idol-makers; his father Azar carved them. The Quran lets us hear his thinking as a young man. He looked at a star and said, this is my lord; when it set he said, I do not love things that set. The moon rose, and the sun, larger each time, and each one set. He concluded aloud: I have turned my face toward Him who created the heavens and the earth, as a true believer, and I am not of those who associate others with Him. Surah al-An'am adds that this was Allah's argument given to him, and that he was shown the kingdom of the heavens and the earth so that he might have certainty.",
    "He asked his father and his people what they worshipped. Statues, they said, that we are devoted to. Do they hear you when you call, he asked, or benefit or harm you? They answered that they had found their fathers doing so. He said that he was free of what they worshipped, except the Lord of the worlds. Then he made a plan. When the people went out to their festival, he went to the idols, offered them food, asked why they did not eat, and broke them to pieces, all but the largest, on which he hung the axe.",
    "When they returned and asked who had done this, they brought him before the people. He said: ask the big one, if they can speak. For a moment they turned to themselves and admitted that they were the wrongdoers. Then they went back on it: you know these do not speak. He asked why they worshipped what could neither benefit nor harm them. Their answer was the fire: burn him and support your gods. They built a furnace and threw him in. Allah said: O fire, be coolness and safety for Ibrahim. They had wished him harm, and were made the losers.",
    "He left them, with Lut, for the land Allah had blessed, and was given Ishaq and Ya'qub as a grandson, and made an imam for the people after him." ] },
  { h: "Where it is in the Quran", l: [
    "6:74–83: the star, the moon and the sun, and the argument Allah gave him.",
    "21:51–73: the breaking of the idols, the trial and the fire.",
    "37:83–99: the same story told with his sickness, the glance at the stars and the departure.",
    "19:41–50: his gentle address to his father, my father, why do you worship what does not hear, and his promise to pray for him.",
    "29:16–27: the people's answer, kill him or burn him, and Lut's belief in him.",
    "2:124–131 and 60:4: Ibrahim as imam, builder of the House, and the example of a clean break." ] },
  { h: "Al-Mizan's reading", p: [
    "Tabataba'i reads the star, moon and sun passage not as a period of real doubt but as an argument conducted in public, Ibrahim taking his people's premises and showing where they lead. 'I do not love things that set' is, for him, the key sentence: a lord one can love is a lord who does not leave. He connects it to the seeing of the kingdom mentioned just before, so that Ibrahim argued from certainty, not toward it.",
    "On the idols, he notes that Ibrahim's question, do they hear you, is the Quran's standing test of every object of devotion, and he reads the people's momentary admission, we are the wrongdoers, as the Quran's record that the truth was seen before it was refused." ] },
  { h: "Lessons", l: [
    "Reasoning is an act of faith in the Quran. Ibrahim argued, and Allah calls the argument His gift.",
    "A plan can serve the truth. Ibrahim chose the festival day, left the axe, and let the idols convict themselves.",
    "He stayed tender with his father while rejecting his father's idols: my father, come, I will guide you. Rejecting an idea is not rejecting a person.",
    "The fire was made cool for a man who had already accepted the fire. The rescue came after the submission, not instead of it." ] },
  { h: "Talk about it", l: [
    "What are our idols, the things we treat as if they could help or hurt us, though they cannot?",
    "Ibrahim spoke gently to his father while disagreeing completely. Where do we need that?",
    "Why did the people admit the truth for a moment and then go back?" ] } ],
  kids: [ "Ibrahim's father made statues for people to worship. Ibrahim looked at a star and thought: is that my Lord? But it went away. The moon went away. Even the sun went away. He said: my Lord is the One who made all of these and never goes away.",
    "One day, when everyone was out, Ibrahim broke all the statues except the biggest one, and hung the axe on it. When people asked who did it, he said: ask the big one! They knew statues cannot talk. That was the point.",
    "They were angry and threw him into a huge fire. Allah said: Fire, be cool and safe for Ibrahim. And it was. Ibrahim walked out without a burn." ] },

"Ibrahim, Isma'il and the sacrifice": { sections: [
  { h: "The story", p: [
    "Ibrahim had asked his Lord for a righteous child, and was given good news of a forbearing boy. The Quran gives the next scene in a few lines. When the boy reached the age of walking and working with him, Ibrahim said: my son, I see in a dream that I am sacrificing you, so look, what do you think? The son answered: my father, do what you are commanded; you will find me, if Allah wills, among the patient.",
    "When they had both submitted, and Ibrahim had laid him down on his forehead, the call came: O Ibrahim, you have fulfilled the vision. Thus We reward those who do good. This was indeed the clear trial. And We ransomed him with a great sacrifice, and left for him among later generations: peace be upon Ibrahim.",
    "The Quran does not name the son in the passage. Many commentators, including Tabataba'i, hold that it was Isma'il, because the good news of Ishaq comes after the sacrifice in the same surah, as a further gift, and because the rite is remembered at the Ka'bah that Ibrahim and Isma'il built together. The sacrifice became the feast of Eid al-Adha and the rite of the pilgrims at Mina, and every family that shares an animal that day is repeating what the two of them did on the hill.",
    "Notice what the father did and did not do. He did not act in silence; he told his son and asked what he thought. He did not pretend it was easy; he said, look. And the son's answer was not bravado but a condition: you will find me, if Allah wills, patient." ] },
  { h: "Where it is in the Quran", l: [
    "37:99–113: the prayer for a son, the dream, the conversation, the ransom, and the news of Ishaq.",
    "2:124–129: Ibrahim tried with words and fulfilled them; he and Isma'il raise the foundations of the House.",
    "22:34–37: the sacrifice as a rite for every community, and the verse that neither meat nor blood reaches Allah, only taqwa.",
    "14:35–41: Ibrahim's prayer for Makkah and for his descendants to keep the prayer." ] },
  { h: "Al-Mizan's reading", p: [
    "Tabataba'i reads the dream as a real command conveyed in the way prophets receive commands, and the fulfilment as the full submission of both, not the act itself: you have fulfilled the vision was said when the knife was in place and the will complete. The trial was therefore of the will, and the ransom shows that Allah did not want the boy's life but his father's whole heart.",
    "He argues from the sequence of the surah that the son was Isma'il, and reads 'you will find me, if Allah wills, among the patient' as the model of a believer's promise: no claim about oneself without the condition." ] },
  { h: "Lessons", l: [
    "The hardest obedience in the Quran was done by two people who talked first. Consultation is not the opposite of submission.",
    "Promise with a condition. Isma'il said 'if Allah wills' about his own patience.",
    "Allah does not want the sacrifice; He wants the sacrificer. The ram came once the heart was given.",
    "Eid is the memory of a family that obeyed together. Sharing the meat is the smallest form of what they did." ] },
  { h: "Talk about it", l: [
    "Why did Ibrahim ask his son what he thought, when the command was from Allah?",
    "What is something hard you would do if you were sure Allah asked for it?",
    "On Eid, what are we remembering when we share the meat with neighbours?" ] } ],
  kids: [ "Ibrahim asked Allah for a son and Allah gave him Isma'il. When Isma'il was big enough to help his father, Ibrahim had a dream from Allah: he was sacrificing his son. He told Isma'il and asked him what he thought.",
    "Isma'il said: Father, do what Allah commands. You will find me patient, if Allah wills. They both said yes to Allah. Ibrahim laid his son down.",
    "Then Allah called out: Ibrahim, you have done it! You both obeyed. And He sent a big ram to sacrifice instead. That is why we have Eid al-Adha and share meat with everyone." ] },

"Yusuf in the well and the palace": { sections: [
  { h: "The story", p: [
    "Yusuf told his father a dream: eleven stars, the sun and the moon bowing to him. Ya'qub told him not to tell his brothers, for Satan is a plain enemy to man. The brothers, who thought their father loved Yusuf and his younger brother more, plotted. They asked to take him out to play, and threw him into the bottom of a well, where Allah revealed to him that one day he would tell them of this deed when they did not recognise him. They came to their father at night weeping, with his shirt stained with false blood. Ya'qub said: your souls have made something seem fair to you; so, beautiful patience. A caravan found the boy and sold him for a few dirhams in Egypt, where the governor's wife raised him.",
    "She wanted him. He refused: he is my master, he has treated me well; wrongdoers do not prosper. She pursued him to the door and tore his shirt from behind, and a witness from her family judged by where the shirt was torn. The women of the city gossiped; she invited them, gave them knives and fruit, and brought him out; they cut their hands. He said: my Lord, prison is dearer to me than what they call me to. He was imprisoned despite the signs of his innocence.",
    "In prison two men asked him to interpret their dreams. He preached to them first, then interpreted; one was freed and forgot him for years. When the king dreamed of seven fat cows eaten by seven lean, the freed man remembered. Yusuf explained the dream and gave the plan: sow seven years and store in the ear; seven hard years will consume what you stored; then a year of relief. He refused to leave prison until his case was cleared. The women confessed; the governor's wife said: now the truth is out. The king made him over the storehouses.",
    "His brothers came for grain and did not know him. He kept his brother, by a ruse within the law, and sent them home. Ya'qub, told the news, said again: beautiful patience, and wept until his eyes went white, and said that he complained only to Allah. He sent them back: do not despair of Allah's relief. Before them Yusuf finally said: I am Yusuf and this is my brother. They admitted their wrong. He said: no blame on you today; may Allah forgive you. He sent his shirt; cast over the father's face, it returned his sight. The family came to Egypt and bowed before him, and the dream was complete. He prayed: my Lord, You have given me kingship and taught me the interpretation of events; take me as a Muslim and join me with the righteous." ] },
  { h: "Where it is in the Quran", l: [
    "Surah 12 is the only surah that tells a single story from beginning to end; the Quran calls it the best of narratives (12:3).",
    "12:4–6: the dream. 12:7–20: the well. 12:21–35: the governor's house and the prison. 12:36–57: the dreams and the rise. 12:58–101: the brothers and the reunion. 12:102–111: the lesson drawn.",
    "40:34: Yusuf remembered in Egypt by a later believer, as a prophet whose message the people doubted after his death." ] },
  { h: "Al-Mizan's reading", p: [
    "Tabataba'i reads the whole surah as the story of wilayah, Allah's guardianship of a servant who has given himself wholly to Him. Every blow that fell on Yusuf, the well, the slavery, the accusation, the prison, was turned into the step by which he rose, and the surah says so in its own words: thus We established Yusuf in the land. He singles out Yusuf's refusal in the governor's house as the moment the whole story turns, and reads 'he saw the proof of his Lord' as the servant's certainty, not an external sign.",
    "He gives weight to Ya'qub's beautiful patience, sabr jamil, which he defines as patience without complaint to creatures, and notes that Ya'qub's sorrow and his patience existed together. Patience is not the absence of grief." ] },
  { h: "Lessons", l: [
    "The dream came true after thirty years and three disasters. A promise from Allah has its own clock.",
    "Yusuf refused the woman before he refused the prison. Character is decided in private before it is tested in public.",
    "No blame on you today: forgiveness at the moment of full power is the surah's highest act.",
    "Ya'qub grieved, wept and lost his sight, and still said beautiful patience. Grief and patience are not opposites." ] },
  { h: "Talk about it", l: [
    "What do you think Yusuf said to himself at the bottom of the well?",
    "When he had all the power, he forgave. What makes forgiveness harder when you are strong?",
    "Ya'qub said: do not despair of Allah's relief. What relief are we waiting for, and how do we wait?" ] } ],
  kids: [ "Yusuf had a dream that eleven stars, the sun and the moon bowed to him. His brothers were jealous and threw him into a well. A caravan found him and sold him in Egypt as a servant.",
    "Yusuf was honest and good even when a rich woman tried to make him do wrong, and even when he was put in prison for something he did not do. In prison, Allah let him explain people's dreams.",
    "The king had a strange dream about seven fat cows and seven thin ones. Yusuf explained it meant seven good years and seven hungry years, and told them how to save food. The king put Yusuf in charge of the whole country. Years later his brothers came hungry, and Yusuf forgave them and brought his whole family to live with him." ] },

"Musa and the burning bush": { sections: [
  { h: "The story", p: [
    "Musa was travelling at night with his family from Madyan, where he had spent years as a shepherd after fleeing Egypt. He saw a fire on the side of the mountain and told his family to wait: perhaps I will bring you a brand from it, or find guidance at the fire. When he came to it, he was called: O Musa, I am your Lord, so take off your sandals; you are in the sacred valley of Tuwa. I have chosen you, so listen to what is revealed. I am Allah, there is no god but Me, so worship Me and establish prayer for My remembrance.",
    "Then the questions and the signs. What is that in your right hand, Musa? My staff; I lean on it, I beat down leaves for my sheep, and I have other uses for it. Throw it down. It became a moving snake. Take it and do not fear; We will return it to its former state. Draw your hand to your side; it comes out white, without harm, another sign. Go to Pharaoh; he has transgressed.",
    "Musa's answer is the dua every teacher, parent and speaker has borrowed since: My Lord, expand for me my breast, and ease for me my task, and untie the knot from my tongue so that they understand my speech; and appoint for me a helper from my family, Harun my brother; strengthen my back with him and let him share my task, so that we may glorify You much and remember You much. The reply: you have been granted your request, Musa. Then Allah reminded him of an earlier favour: the basket on the river, the mother's heart, the sister following, the years in Madyan, and: I have made you for Myself.",
    "Go, you and your brother, with My signs, and do not slacken in My remembrance. Speak to him gently; perhaps he will take heed or fear. They were afraid; He said: do not fear, I am with you both, I hear and I see." ] },
  { h: "Where it is in the Quran", l: [
    "20:9–48: the fullest account, with the dua, the reminder of his childhood and the command to speak gently.",
    "28:29–35: the same scene with Musa's fear about the man he had killed and his request for Harun as a helper because he is more eloquent.",
    "27:7–14: the fire, the blessed one at it, and the nine signs for Pharaoh.",
    "26:10–17 and 79:15–26: the commission in brief." ] },
  { h: "Al-Mizan's reading", p: [
    "Tabataba'i reads the first words at the fire as the whole of religion in order: I am your Lord; there is no god but Me; worship Me; establish prayer for My remembrance. Prayer is named as the form remembrance takes. He treats the questions about the staff as Allah's way of making Musa familiar with what is about to become a sign, so that the miracle is placed in something ordinary and known.",
    "On the dua, he observes that Musa asked first for inner capacity, the opened breast, and only then for the tongue and the helper; and that 'so that we may glorify You much' is the purpose Musa gives for wanting a brother beside him. The mission's aim is worship, not victory." ] },
  { h: "Lessons", l: [
    "Musa went to the fire for a brand and found his Lord. Errands can be callings.",
    "He named what he was afraid of, his tongue, his past, his loneliness, and asked for each. A dua can be specific.",
    "Allah's first favour was named: the basket, the mother, the sister. Before the great task, remember how you have been carried so far.",
    "Speak to Pharaoh gently. If gentleness was commanded toward the worst man alive, it is commanded toward everyone else." ] },
  { h: "Talk about it", l: [
    "Musa asked for a helper from his family. Who is the helper you would ask for?",
    "What is your 'knot in the tongue', the thing you find hard to say?",
    "Why did Allah tell Musa to speak gently to Pharaoh?" ] } ],
  kids: [ "Musa was walking at night with his family and saw a fire on a mountain. He went to get some fire to keep them warm. When he got there, Allah spoke to him and told him: take off your shoes, this is a holy place.",
    "Allah showed Musa two miracles: his walking stick turned into a snake, and his hand shone white like a light. Then Allah told him to go to Pharaoh, the cruel king, and tell him to let the people go.",
    "Musa was scared. He said: Allah, make my heart strong, make my job easy, help me speak clearly, and let my brother Harun come with me. Allah said: yes, you have everything you asked. We still say Musa's dua before hard things." ] },

"Musa and al-Khidr": { sections: [
  { h: "The story", p: [
    "Musa set out with his young companion to the meeting of the two seas, saying that he would not stop until he reached it, even if he had to go on for ages. At the place, they forgot their fish, which took its way into the sea. When Musa asked for the meal and the boy remembered, Musa said: that is what we were seeking, and they retraced their steps. There they found a servant of Allah, given mercy and taught knowledge from His presence. Musa asked: may I follow you so that you teach me of the right guidance you were taught? He answered: you will not be able to have patience with me; how could you be patient with what your knowledge does not encompass? Musa promised patience and obedience. The condition was set: ask me about nothing until I mention it to you.",
    "They boarded a boat, and the man made a hole in it. Musa objected: have you holed it to drown its people? You have done a dreadful thing. Did I not say you would not be able to be patient? Musa apologised. They met a boy and the man killed him. Musa objected harder: an innocent soul? The second warning. Musa set his own limit: if I ask you about anything after this, do not keep me with you. They came to a town whose people refused them food, and the man found a wall about to fall and set it straight. Musa said: you could have taken payment for that. This is the parting between you and me.",
    "Then the explanations. The boat belonged to poor people who worked the sea; a king was seizing every sound boat, so the damage saved it. The boy's parents were believers, and he would have burdened them with rebellion and disbelief; they would be given one better in purity and nearer in mercy. The wall belonged to two orphan boys in the town, with a treasure under it left by a righteous father; their Lord willed that they reach maturity and take it out, as a mercy from Him. And I did not do it of my own accord. That is the explanation of what you could not bear with patience.",
    "The Quran places this story in the middle of Surah al-Kahf, the surah read every Friday, between the two gardens and Dhul-Qarnayn." ] },
  { h: "Where it is in the Quran", l: [
    "18:60–82: the whole story. The companion is not named in the Quran; the narrations call him al-Khidr.",
    "18:65: given mercy from Us and taught knowledge from Our presence, the phrase that defines what he had.",
    "Compare 12:21 and 12:100: Allah is in control of His affair, the thread in Yusuf that this story makes visible." ] },
  { h: "Al-Mizan's reading", p: [
    "Tabataba'i reads the story as the meeting of two kinds of knowledge: the outward law that Musa carried, which judges acts by what appears, and knowledge of the realities behind events, which Allah gives to whom He wills. Musa was not wrong to object; by the law he was right each time. The lesson is that the law judges appearances while Allah's decree works through hidden mercies, and that a believer who sees a calamity may be looking at a rescue.",
    "He notes the care of the final sentence, I did not do it of my own accord, which places all three acts under command, and reads the three explanations as three faces of mercy: the preserved livelihood, the protected faith, the kept inheritance." ] },
  { h: "Lessons", l: [
    "Musa, a prophet with a Book, asked to be a student. Nobody is too senior to learn.",
    "What looks like damage can be protection. The holed boat was the saved boat.",
    "Patience with what you do not understand is a form of knowledge.",
    "A righteous father's goodness was kept for his orphans under a wall. What parents do lasts past them." ] },
  { h: "Talk about it", l: [
    "Has something that seemed bad for you turned out to be the thing that saved you?",
    "Musa promised patience three times and broke it three times. Why is that hard even for a prophet?",
    "What might our father's or mother's goodness be keeping safe for us without our knowing?" ] } ],
  kids: [ "Musa wanted to learn from a special servant of Allah who knew secret things. The man said: you will not be patient with me, because you will not understand what I do. Musa promised not to ask questions.",
    "They got on a boat and the man made a hole in it. Musa said: why! Then the man knocked down a wall and built it again for free. Musa said: why! Each time the man said: I told you that you would not be patient.",
    "Then the man explained. The hole saved the boat from a bad king who was taking all the good boats. The wall had treasure under it for two orphan children. Sometimes things look bad, but Allah is keeping something good hidden inside them." ] },

"Dawud and Jalut": { sections: [
  { h: "The story", p: [
    "After Musa, the leaders of Bani Israel asked their prophet to appoint a king so that they might fight in Allah's way. He asked whether they would really fight if fighting were prescribed. They said: why would we not, when we have been driven from our homes and our children? When it was prescribed, most turned away. The prophet announced that Allah had appointed Talut as king. They objected: how can he have kingship over us when we have more right to it and he has not been given wealth? The answer: Allah has chosen him and increased him in knowledge and stature. The sign of his kingship would be the Ark returning to them, carried by angels.",
    "Talut set out with the army and told them: Allah will test you with a river. Whoever drinks from it is not of me, and whoever does not taste it is of me, except for a handful scooped by hand. They drank, all but a few. When he and those who believed with him had crossed, the rest said: we have no strength today against Jalut and his army. But those who were certain they would meet Allah said: how many a small company has overcome a large company by Allah's leave. Allah is with the patient.",
    "Facing Jalut they prayed: our Lord, pour patience upon us, make our feet firm and help us against the disbelieving people. They routed them by Allah's leave, and Dawud killed Jalut. Allah gave Dawud the kingship and wisdom and taught him of what He willed. The passage ends with a principle: if Allah did not check some people by means of others, the earth would be corrupted.",
    "Dawud's later life fills other surahs: the mountains and birds echoing his praise, iron made soft for him, his judgement between the two litigants and his quick repentance, and the Zabur given to him." ] },
  { h: "Where it is in the Quran", l: [
    "2:246–251: the request for a king, Talut, the river, the small company, Dawud and Jalut.",
    "38:17–26: Dawud's strength, the mountains and birds, the two litigants and his repentance.",
    "34:10–11 and 21:79–80: iron softened, the coats of mail, the mountains glorifying with him.",
    "4:163 and 17:55: the Zabur given to Dawud." ] },
  { h: "Al-Mizan's reading", p: [
    "Tabataba'i reads the river as a test of self-control before the test of courage: a people who could not hold back their thirst could not hold a line. He connects the objection to Talut, he has not been given wealth, with the Quran's repeated correction that leadership follows knowledge and capacity rather than property, and he treats 'how many a small company' as the believers' general law, spoken by those who were certain they would meet Allah: certainty about the Hereafter produces courage here.",
    "He reads the closing principle, checking some by others, as the Quran's statement that struggle is built into the order of the world and is itself a mercy, since without it corruption would cover the earth." ] },
  { h: "Lessons", l: [
    "The first test was a drink of water. The small discipline decides who is there for the big one.",
    "Numbers do not decide. Patience and certainty do, by Allah's leave.",
    "The people wanted a rich king; Allah chose a knowledgeable, strong one. We still confuse wealth with fitness to lead.",
    "A young shepherd ended the battle. Age and rank are not the measure of what Allah can do through a person." ] },
  { h: "Talk about it", l: [
    "Why did Talut test the army with a river before the battle?",
    "What is a 'handful of water' in your life, a small thing that decides whether you can do the big thing?",
    "When have a few people done what many could not?" ] } ],
  kids: [ "The people of Bani Israel wanted a king to lead them in a battle. Allah chose Talut. Some people grumbled because he was not rich. But Allah chose him because he was wise and strong.",
    "On the way to the battle Talut said: there is a river ahead. Do not drink more than one handful. Most of the soldiers drank and drank. Only a few obeyed. Those few were the real team.",
    "The enemy had a giant called Jalut. The small team prayed: Allah, give us patience and make our feet strong. A young shepherd boy called Dawud fought Jalut with a sling and won. Later Dawud became a king and a prophet." ] },

"Sulayman and the ant": { sections: [
  { h: "The story", p: [
    "Dawud and Sulayman were given knowledge, and they said: praise be to Allah, who has favoured us over many of His believing servants. Sulayman inherited from Dawud and said: O people, we have been taught the speech of birds, and we have been given of all things; this is the clear favour. His armies of jinn, men and birds were gathered and marched in order.",
    "When they came to the valley of the ants, an ant said: O ants, enter your dwellings, lest Sulayman and his armies crush you without knowing. Sulayman smiled, laughing at her words, and said: My Lord, enable me to be grateful for Your favour which You have bestowed on me and on my parents, and to do righteous work that pleases You, and admit me by Your mercy among Your righteous servants.",
    "The surah goes on to the hoopoe, who was missing at the inspection and returned with news of Sheba, a queen on a great throne whose people prostrated to the sun. Sulayman sent her a letter beginning with the basmala, calling her to come in submission. She consulted her council, sent a gift, which he refused, and finally came. Her throne was brought before her arrival by one who had knowledge of the Book, in the blink of an eye, and Sulayman said: this is from my Lord's favour, to test whether I will be grateful or ungrateful. She entered the palace, mistook its glass floor for water, and said: my Lord, I have wronged myself, and I submit with Sulayman to Allah, Lord of the worlds.",
    "The ant's sentence has three parts the surah seems to want us to notice: she warned her people, she assumed the best of Sulayman, 'without knowing', and she spoke to be heard. The king who could command the wind stopped for her." ] },
  { h: "Where it is in the Quran", l: [
    "27:15–19: the inheritance, the speech of birds, the ant and the prayer.",
    "27:20–44: the hoopoe, the letter to Sheba, the throne and the queen's submission.",
    "34:12–14: the wind, the jinn's labour, and Sulayman's death unknown until the staff was eaten.",
    "38:30–40: the horses, his return to his Lord, and the kingdom asked for.",
    "21:78–82: his judgement with Dawud on the field and the wind subjected to him." ] },
  { h: "Al-Mizan's reading", p: [
    "Tabataba'i treats the understanding of the ant as real, not figurative, and part of the knowledge Sulayman says he was taught. The prayer that follows is, in his reading, the response of a servant who sees his gifts and asks for the one thing gifts cannot supply: the ability to be grateful. He notes that gratitude is asked for as a gift, awzi'ni, and that Sulayman includes his parents in it, since his favour came through them.",
    "He reads the story of Sheba as the surah's demonstration that power, knowledge and wealth can be held by a prophet without harm to his servanthood, which is why Sulayman says of the throne brought in a glance: this is to test whether I will be grateful." ] },
  { h: "Lessons", l: [
    "The ant thought well of the king: 'without knowing'. Husn al-zann is the ant's first lesson.",
    "The greatest king in the Quran laughed at an ant's warning and then prayed. Power that can still smile and still kneel is safe.",
    "Gratitude is a gift to ask for, not only a feeling to have.",
    "The ant warned her people. Leadership is sounding the alarm for others before saving yourself." ] },
  { h: "Talk about it", l: [
    "What did Sulayman do first after understanding the ant: command, or pray? Why?",
    "The ant assumed Sulayman would not hurt them on purpose. When do we assume the worst about people?",
    "If you could understand animals for one day, which would you listen to?" ] } ],
  kids: [ "Sulayman was a king and a prophet who could understand what birds and animals said. He had a huge army of people, jinn and birds.",
    "One day the army was walking near a valley full of ants. A little ant shouted: everyone, go into your houses, or Sulayman's army will step on you by accident! Sulayman heard her and smiled.",
    "Then Sulayman said a dua: Allah, help me to thank You for all You gave me and my parents, and help me do good things that make You happy. Even the biggest king stopped to listen to the smallest ant." ] },

"Yunus in the whale": { sections: [
  { h: "The story", p: [
    "Yunus was sent to a city of a hundred thousand or more. He called them and they refused, and he warned them of a punishment. Before permission came, he left them in anger, thinking that Allah would not constrain him. He went to a laden ship. When it was in danger, lots were drawn to lighten it, and he was among the losers and was thrown into the sea, and the whale swallowed him while he was blameworthy. Had he not been of those who glorify Allah, he would have stayed in its belly until the Day they are raised.",
    "In the darkness, the darkness of the night, the sea and the whale's belly, he called: there is no god but You, glory be to You; I was indeed among the wrongdoers. The Quran says: so We answered him and saved him from the distress, and thus We save the believers. He was cast on the bare shore, sick, and a gourd plant was made to grow over him. He was sent back to his people, and they believed, so they were given enjoyment for a time.",
    "Yunus's people are the one nation in the Quran that repented before the punishment fell and were spared: why was there not a town that believed and whose faith benefited it, except the people of Yunus? When they believed, We removed from them the punishment of disgrace in this life.",
    "The Prophet was told: be patient for your Lord's judgement and do not be like the companion of the fish, when he called out while choking with grief. And the Prophet taught that no Muslim calls with the words of Yunus but is answered." ] },
  { h: "Where it is in the Quran", l: [
    "21:87–88: Dhun-Nun's departure, the call in the darkness, and the promise: thus We save the believers.",
    "37:139–148: the ship, the lots, the whale, the gourd, and the hundred thousand who believed.",
    "10:98: the people of Yunus, the one town whose faith came in time.",
    "68:48–50: the warning to the Prophet not to be like the companion of the fish, and the mercy that caught Yunus.",
    "4:163 and 6:86: Yunus among the messengers." ] },
  { h: "Al-Mizan's reading", p: [
    "Tabataba'i is careful about Yunus's fault. A prophet does not sin, so the leaving in anger was a departure before permission that was blameworthy relative to his station, not a disobedience of a command. He reads 'thinking We would not constrain him' as Yunus assuming he was free to go, and the whale as the constraint. The dua is, in his reading, perfect because it contains nothing but acknowledgement: no request, only tawhid, glorification and confession, and Allah answered a request that was not even made.",
    "On the people of Yunus he reads 10:98 as a law of Allah's mercy: a punishment announced can be lifted by repentance before it falls, which the surah offers to Makkah as a real possibility." ] },
  { h: "Lessons", l: [
    "The best dua in distress asks for nothing. It says who Allah is, and who I am.",
    "Being in the dark is not being abandoned. Yunus was heard inside three darknesses.",
    "Leaving early, even from something hard and unjust, has a cost. Permission matters.",
    "A whole city turned in time. Repentance before the deadline is accepted, and the deadline is not known." ] },
  { h: "Talk about it", l: [
    "Why do you think Yunus's dua has no request in it?",
    "What is a place or time that feels like the whale's belly, and what could we say there?",
    "The people of Yunus changed their minds before it was too late. What makes a whole family change direction?" ] } ],
  kids: [ "Yunus was a prophet who told his people about Allah, but they would not listen. He got angry and left before Allah told him he could. He got on a ship, but a storm came, and he was thrown into the sea.",
    "A huge whale swallowed him. Inside the whale it was dark, dark, dark. Yunus did not give up. He said: there is no god but You, Allah, You are perfect, I was wrong.",
    "Allah heard him and the whale put him safely on the beach. Allah grew a plant to shade him. Then Yunus went back to his people, and this time they all believed. When you are scared in the dark, you can say Yunus's words." ] },

"Maryam under the palm tree": { sections: [
  { h: "The story", p: [
    "Maryam's mother had vowed what was in her womb to the service of the sanctuary, and when a girl was born she named her Maryam and asked Allah's protection for her and her children from Satan. Zakariyya took charge of her. Whenever he entered her chamber he found provision with her, and asked where it came from; she said: from Allah, who provides without measure. It was there that Zakariyya prayed for a child of his own.",
    "She withdrew from her family to an eastern place and screened herself. Allah sent His Spirit to her in the form of a well-made man. She said: I seek refuge in the Merciful from you, if you are God-fearing. He said: I am only a messenger of your Lord, to give you a pure boy. How can I have a boy when no man has touched me and I have not been unchaste? He said: your Lord says, it is easy for Me, and We will make him a sign for people and a mercy from Us; it is a matter decreed.",
    "She conceived and withdrew to a far place. The pains of labour drove her to the trunk of a palm tree, and she said: would that I had died before this and been forgotten. A voice called from below her: do not grieve; your Lord has placed a stream beneath you. Shake the trunk of the palm toward you; it will drop fresh ripe dates on you. Eat and drink and be comforted. If you see anyone, say: I have vowed a fast to the Merciful and will not speak today to any human.",
    "She brought him to her people carrying him. They said: Maryam, you have done an unheard-of thing; sister of Harun, your father was not a bad man and your mother was not unchaste. She pointed to him. They said: how can we speak to a child in the cradle? He said: I am the servant of Allah; He has given me the Book and made me a prophet, and made me blessed wherever I am, and enjoined on me prayer and zakat as long as I live, and dutiful to my mother. Peace be on me the day I was born, the day I die and the day I am raised alive." ] },
  { h: "Where it is in the Quran", l: [
    "19:16–36: the annunciation, the palm tree, and the infant's speech.",
    "3:35–47: her mother's vow, her upbringing with Zakariyya, the provision, and the angels' words to her.",
    "66:12 and 21:91: Maryam who guarded her chastity, made with her son a sign for the worlds.",
    "3:42: chosen and purified and chosen above the women of the worlds.",
    "5:75 and 5:110–118: the Messiah son of Maryam and his mother, who both ate food; the table and the final questioning." ] },
  { h: "Al-Mizan's reading", p: [
    "Tabataba'i reads the palm-tree verses as a lesson in how Allah provides: the stream and the dates were there, and she was told to shake the trunk. Provision came by her own effort joined to Allah's arrangement, and he draws from it the rule that reliance does not excuse the hand from working. Her cry, would that I had died, he reads as the natural fear of a pure woman for her honour, not despair of Allah, and the comfort came in three parts: do not grieve, eat and drink, keep silent and let Allah answer for you.",
    "He gives her a station the Quran gives few: she is addressed by angels, called a siddiqa, a truthful one, and ranked above the women of the worlds, and he considers her among those Allah speaks to without being prophets, a muhaddatha." ] },
  { h: "Lessons", l: [
    "Shake the trunk. Allah's provision usually asks for one movement from us.",
    "Silence can be the strongest defence. She vowed a fast of speech and let the truth speak.",
    "'Dutiful to my mother' is in the infant's first sentence. The Quran places a mother's right inside a prophet's commission.",
    "Fear is not a failure of faith. Maryam was afraid, said so, and was comforted, not rebuked." ] },
  { h: "Talk about it", l: [
    "Why did Allah ask Maryam to shake the tree instead of simply dropping the dates?",
    "What is the hardest thing about staying quiet when people say something untrue about you?",
    "Isa's first words praised his mother. What would you want your first words to say about yours?" ] } ],
  kids: [ "Maryam was a very good girl who lived in the house of worship. Allah always sent her food, and when the prophet Zakariyya asked where it came from, she said: from Allah.",
    "An angel came and told her she would have a special baby, Isa, even though she had no husband. It was a miracle from Allah. When the baby was about to come, she was alone and scared and leaned against a palm tree.",
    "A voice said: do not be sad. There is a stream under you. Shake the tree and fresh dates will fall. Eat, drink and be calm. When people asked questions, baby Isa spoke from her arms and said: I am Allah's servant, and I am kind to my mother." ] },

"The youths of the cave": { sections: [
  { h: "The story", p: [
    "A group of young men believed in their Lord in a city that worshipped others, and Allah increased them in guidance. They stood up and said: our Lord is the Lord of the heavens and the earth; we will never call on any god besides Him, or we would have said something outrageous. These people of ours have taken gods besides Him; why do they not bring a clear authority for them? They decided together: when you have withdrawn from them and what they worship besides Allah, take refuge in the cave; your Lord will spread His mercy for you and arrange your affair with ease.",
    "They prayed as they entered: our Lord, give us mercy from Yourself and arrange for us right guidance in our affair. Allah struck their ears in the cave for a number of years. The Quran describes them asleep: you would think them awake while they slept; We turned them to the right and to the left, and their dog stretched its forelegs at the entrance. Had you looked at them you would have turned from them in flight, filled with fear. The sun, when it rose, moved away from their cave to the right, and when it set, passed them on the left.",
    "Then Allah raised them so that they would ask one another. How long have you stayed? A day, or part of a day. Your Lord knows best how long. Send one of you with this silver coin to the city, let him see which food is purest and bring provision from it, and let him be careful and not let anyone know of you; for if they find you, they will stone you or force you back to their religion. The coin was centuries old, and so the town learned of them, and learned that Allah's promise is true and that there is no doubt about the Hour. They argued over them, and the ones who prevailed said: we will build over them a place of worship.",
    "The Quran gives the number of years, three hundred and nine, and refuses the argument about how many they were: say, my Lord knows best their number. The surah then teaches the Prophet not to say of anything, I will do it tomorrow, without adding if Allah wills." ] },
  { h: "Where it is in the Quran", l: [
    "18:9–26: the entire story, the only place it is told.",
    "18:13–14: We relate to you their story in truth; We strengthened their hearts when they stood up.",
    "18:23–24: the instruction to say 'if Allah wills', placed at the story's end.",
    "18:28: keep yourself patient with those who call on their Lord morning and evening, the verse that follows." ] },
  { h: "Al-Mizan's reading", p: [
    "Tabataba'i reads the story as a sign of the resurrection placed inside the surah's larger argument, and he notes that the Quran tells it to remove the strangeness of the resurrection: a people who slept three centuries and woke thinking it a day are a small resurrection shown to a town. He emphasises that they withdrew from society only after society left them no room to believe, and that their withdrawal was itself an act of faith, with a prayer, not a flight from responsibility.",
    "On the dog, the sun and the turning, he reads the details as the Quran's way of saying that their preservation was Allah's management down to the smallest matter, and he takes 'say, if Allah wills' as the lesson the Prophet himself was to draw from a story about time." ] },
  { h: "Lessons", l: [
    "They were young, and the Quran says so with honour. Youth is the age of standing up.",
    "Their first move after deciding was a dua: arrange our affair. Planning and prayer went together.",
    "Buy the purest food, and be careful. Even the hidden believer is told to eat well and to be wise.",
    "The Quran refused the argument about their number. Some details are not worth the fight." ] },
  { h: "Talk about it", l: [
    "Why do you think Allah tells us about the dog at the entrance?",
    "What would you find most changed if you woke up in three hundred years?",
    "The town built a place of worship over them. What should we build over a story like this?" ] } ],
  kids: [ "Some young men believed in Allah in a town where the king wanted everyone to worship statues. They said: our Lord is the Lord of the heavens and the earth, and we will never worship anyone else.",
    "They ran away to hide in a cave, with their dog lying at the door. They prayed: Allah, be kind to us and help us. Allah made them fall asleep, and they slept for three hundred years! The sun never shone on them and they were turned over so they stayed safe.",
    "When they woke up, they thought it was the next day. One of them went to buy food with an old coin. The shopkeeper stared at the coin from hundreds of years ago. That is how everyone learned that Allah can keep people safe for as long as He wants, and can wake them up again." ] },

"The man with two gardens": { sections: [
  { h: "The story", p: [
    "The Quran gives the parable of two men. To one, Allah gave two gardens of grapevines, surrounded by date palms, with crops between them; each garden gave its full yield without failing, and a river ran through them. He had fruit, and wealth, and he said to his companion while talking with him: I have more wealth than you and more men. He entered his garden wronging himself and said: I do not think this will ever perish, and I do not think the Hour will come; and if I am ever returned to my Lord, I will surely find something better than this in return.",
    "His companion said: do you disbelieve in Him who created you from dust, then from a drop, then shaped you as a man? As for me, He is Allah, my Lord, and I will not associate anyone with my Lord. Why, when you entered your garden, did you not say: what Allah wills; there is no power except with Allah? If you see me as less than you in wealth and children, perhaps my Lord will give me better than your garden and send on it a bolt from the sky so that it becomes a slippery plain, or its water sinks into the ground so that you can never find it.",
    "His fruit was destroyed, and he began to wring his hands over what he had spent on it, with its trellises fallen down, saying: would that I had not associated anyone with my Lord. He had no party to help him besides Allah, and he could not help himself. There, the surah says, protection belongs to Allah, the True; He is best in reward and best in outcome.",
    "The parable continues into the next verse: the life of this world is like water that We send down from the sky, with which the earth's plants mingle, and then they become dry straw scattered by the winds. Wealth and children are the adornment of this life, but the lasting good deeds are better with your Lord." ] },
  { h: "Where it is in the Quran", l: [
    "18:32–44: the parable of the two men and the two gardens.",
    "18:45–46: the water and the dry straw; wealth and children as adornment; the lasting good deeds.",
    "68:17–33: the companion parable of the owners of the garden who planned to leave nothing for the poor.",
    "28:76–82: Qarun, the same lesson told as history rather than parable." ] },
  { h: "Al-Mizan's reading", p: [
    "Tabataba'i reads the garden owner's fault not as atheism but as a hidden shirk: he attributed the gardens' permanence to themselves and to his own standing, which is why the companion's remedy is a sentence, ma sha Allah la quwwata illa billah, that places all power with Allah. His 'if I am returned I will find better' is the voice of a man who thinks wealth here proves favour there, which the Quran denies throughout.",
    "He sees the parable's placement in al-Kahf as deliberate: after the youths who left everything for faith comes the man who kept everything and lost faith, and both end at the same verse: protection belongs to Allah." ] },
  { h: "Lessons", l: [
    "Say ma sha Allah, la quwwata illa billah when you enter what you own. The sentence is the protection.",
    "Wealth is adornment, not evidence. A full garden says nothing about the Hereafter.",
    "The poorer companion was not silent. Speaking the truth to a richer friend is part of friendship.",
    "What Allah gave 'without failing' failed in a night. Only the lasting good deeds have no night." ] },
  { h: "Talk about it", l: [
    "What is our 'garden', the thing we feel sure will always be there?",
    "Why did the rich man think the Hereafter would be even better for him?",
    "The poor friend said a short sentence that would have saved the garden. When do we forget to say it?" ] } ],
  kids: [ "Allah tells a story about two friends. One had two beautiful gardens full of grapes and dates with a river running through them. He got proud and said: this will last forever, and I am better than you because I have more.",
    "His friend said: you should say ma sha Allah, whatever Allah wants, there is no power except with Allah. Everything you have is from Him.",
    "That night the gardens were destroyed. The proud man held his head in his hands and said: I wish I had remembered Allah. So when you see something you love, say ma sha Allah." ] },

"Luqman's advice to his son": { sections: [
  { h: "The story", p: [
    "The Quran says: We gave Luqman wisdom: be grateful to Allah. Whoever is grateful is grateful for his own soul, and whoever is ungrateful, Allah is free of need, worthy of praise. That is the frame: wisdom's first act is thanks. Luqman is not called a prophet; he is a wise man, and the tradition remembers him as a man of dark skin and plain work who was given hikmah, and whose counsel to his son the Quran chose to preserve.",
    "He said to his son while advising him: my son, do not associate anything with Allah; association is a tremendous wrong. Then the Quran itself interrupts with the right of parents: We enjoined on man concerning his parents, his mother carried him in weakness upon weakness and his weaning is in two years, be grateful to Me and to your parents; but if they strive to make you associate with Me what you have no knowledge of, do not obey them, yet keep company with them in this world kindly.",
    "Luqman continues: my son, if it is the weight of a mustard seed and it is inside a rock or in the heavens or in the earth, Allah will bring it out; Allah is subtle, aware. My son, establish prayer, enjoin what is right, forbid what is wrong, and be patient over what befalls you; that is of the matters requiring resolve. Do not turn your cheek from people in contempt, and do not walk through the earth exultantly; Allah does not love any self-deluded boaster. Be moderate in your pace and lower your voice; the most hateful of voices is the voice of donkeys.",
    "Eight pieces of advice, from the inside out: tawhid, then the awareness that nothing is hidden, then prayer, then responsibility to others, then patience, then humility in the face, the walk and the voice." ] },
  { h: "Where it is in the Quran", l: [
    "31:12–19: the gift of wisdom and the whole counsel.",
    "31:14–15: the right of parents, set inside the counsel so that gratitude to Allah and to parents are one command.",
    "17:23–24 and 46:15: the same right of parents stated elsewhere.",
    "25:63: the servants of the Merciful who walk gently, the walk Luqman describes." ] },
  { h: "Al-Mizan's reading", p: [
    "Tabataba'i defines hikmah, from this passage, as knowledge joined to the action it calls for, so that the first thing wisdom does is thank. He reads the order of the counsel as a curriculum: belief, then the sense of being seen, then worship, then social duty, then conduct of the body. He notes the Quran's placement of the parents' verses within Luqman's speech, and takes it as the Book's way of saying that a father's advice to his son includes the son's duty to the father, and its limit: no obedience in shirk, but kindness even then.",
    "On the voice of donkeys, he reads it as the Quran's dislike of loudness as such: a raised voice is a claim to a space that is not one's own." ] },
  { h: "Lessons", l: [
    "Wisdom's first act is gratitude; the Quran says so before Luqman says a word.",
    "Children are owed truth about tawhid first, not last.",
    "The mustard seed in the rock: character is what we do where nothing can be seen.",
    "The walk and the voice are part of religion. How we enter a room is a kind of belief." ] },
  { h: "Talk about it", l: [
    "Which of Luqman's eight pieces of advice is hardest for you, and why?",
    "Why does the Quran put the right of parents in the middle of a father's advice?",
    "What does a moderate walk look like? What does a lowered voice sound like at home?" ] } ],
  kids: [ "Luqman was a very wise man, and Allah kept his advice to his son in the Quran so every child can hear it.",
    "He said: my son, worship only Allah. Allah sees everything, even a tiny seed hidden inside a rock. Pray. Tell people to do good. Be patient when things go wrong.",
    "He also said: do not be proud and turn your face away from people. Do not walk like a show-off. Walk calmly and talk quietly, because the loudest voice of all is a donkey's!" ] },

"Qarun and his treasure": { sections: [
  { h: "The story", p: [
    "Qarun was of the people of Musa, and he oppressed them. Allah had given him such treasures that the keys alone would weigh down a band of strong men. His people said to him: do not exult; Allah does not love the exultant. Seek, with what Allah has given you, the home of the Hereafter, and do not forget your share of this world; do good as Allah has done good to you, and do not seek corruption in the land; Allah does not love the corrupters.",
    "His answer is the sentence the Quran records against him: I was only given it because of knowledge I have. The Quran replies that Allah had destroyed before him generations stronger and richer, and that the criminals are not even asked about their sins. He went out before his people in his finery, and those who desired this life said: would that we had the like of what Qarun was given; he is truly a man of great fortune. Those who had been given knowledge said: woe to you; Allah's reward is better for one who believes and does right, and none receives it except the patient.",
    "Then: We caused the earth to swallow him and his house, and he had no party to help him against Allah, nor could he help himself. The ones who had envied him the day before now said: it is Allah who extends and restricts provision to whom He wills of His servants; had Allah not been gracious to us, He would have caused the earth to swallow us too. The disbelievers never prosper.",
    "The surah closes the story with a verse that has become a rule: that home of the Hereafter We assign to those who do not desire exaltedness in the earth or corruption, and the good end is for the God-conscious." ] },
  { h: "Where it is in the Quran", l: [
    "28:76–83: the whole account, with the people's counsel, Qarun's claim, the procession and the swallowing.",
    "29:39–40: Qarun named with Pharaoh and Haman, each taken by his own kind of punishment.",
    "40:23–24: Musa sent to Pharaoh, Haman and Qarun.",
    "18:32–44: the man with two gardens, the same claim without the earthquake." ] },
  { h: "Al-Mizan's reading", p: [
    "Tabataba'i finds the whole of Qarun in his one sentence, 'because of knowledge I have': the claim that wealth is earned by one's own cleverness, which severs it from Allah and turns it into a reason for exultation. He reads the people's counsel as the Quran's balanced economics: seek the Hereafter with your wealth, do not forget your share here, do good, do not corrupt. Qarun was condemned for the attitude, not for the treasure.",
    "He stresses the before-and-after of the crowd: the ones who envied him on the day of the procession understood the next morning. The story is as much about the spectators as about Qarun, and the closing verse gives the test: the Hereafter belongs to those who do not want to be high in the earth." ] },
  { h: "Lessons", l: [
    "'I earned it' is the sentence that turned treasure into a grave. Barakah leaves what we claim as our own.",
    "Envy of the rich evaporates in one morning. Do not build your wishes on someone else's procession.",
    "The advice to Qarun was balanced: do not forget your share of this world. The Quran is not against wealth; it is against exultation.",
    "The keys weighed down strong men. Possessions carry their own weight on the one who holds them." ] },
  { h: "Talk about it", l: [
    "Is there anything we say 'I earned this' about, forgetting who gave the ability?",
    "The crowd envied Qarun and then thanked Allah they were not him. Which crowd are we in?",
    "What is our 'share of this world' that the Quran says not to forget?" ] } ],
  kids: [ "Qarun was so rich that strong men could not carry the keys to his treasure rooms. People told him: be grateful to Allah and help others. He said: no, I got all this because I am clever.",
    "One day he walked through the town showing off his gold and fine clothes. Some people said: I wish I had what Qarun has!",
    "Then the ground opened and swallowed Qarun and his whole house. The next day the same people said: thank Allah we were not like him. Everything we have is from Allah, not from being clever." ] },

"The people of the elephant": { sections: [
  { h: "The story", p: [
    "In the year the Prophet was born, Abraha, the ruler of Yemen under the Abyssinians, built a great church in Sana'a and wanted the Arabs' pilgrimage turned to it. When the Ka'bah remained the Arabs' House, he marched on Makkah with an army and a war elephant to destroy it. The Quraysh could not fight such an army. Abd al-Muttalib, the Prophet's grandfather, who kept the House, asked only for his own camels back and said of the House: it has a Lord who will protect it. The people of Makkah withdrew to the hills.",
    "The Quran's account is five verses: have you not seen how your Lord dealt with the companions of the elephant? Did He not make their plan go astray? He sent against them birds in flocks, striking them with stones of baked clay, and made them like eaten straw. The tradition records that the elephant knelt at the edge of the sanctuary and would not go forward, and that the army perished.",
    "The next surah, Quraysh, follows directly in the mushaf and is read with it: for the security of Quraysh, their security in the journey of winter and summer, let them worship the Lord of this House, who fed them against hunger and secured them from fear. Makkah's safety and trade, the Quran says, are owed to the House's Lord, and the proper answer is worship.",
    "The year became the Arabs' calendar: the Year of the Elephant. The Prophet was born in it, and the people who saw the army destroyed were the ones who, forty years later, heard the first revelation in the same city." ] },
  { h: "Where it is in the Quran", l: [
    "Surah 105, al-Fil: the whole account.",
    "Surah 106, Quraysh: the sequel, read with it; the security and the two journeys.",
    "3:96–97: the first House appointed for people, at Bakkah, a safe sanctuary.",
    "2:125–129: Ibrahim and Isma'il raising its foundations, and the prayer for a messenger from among its people." ] },
  { h: "Al-Mizan's reading", p: [
    "Tabataba'i reads al-Fil as a reminder addressed to the Quraysh of an event their elders had seen, so that 'have you not seen' means 'you know this'. The protection of the House was a favour to Quraysh in particular, which is why Surah Quraysh follows: a people protected and fed should worship the Protector. He takes the birds and the stones literally, as the narrations give them, and sees no reason to explain them away.",
    "He notes that the Quran attributes the deliverance wholly to Allah, with no human battle, which made it a sign for the city that a Prophet would soon be sent to, and a warning that a House Allah defended against an army is not to be dishonoured by its own keepers." ] },
  { h: "Lessons", l: [
    "It has a Lord who will protect it: Abd al-Muttalib's sentence is the surah's whole theology.",
    "Allah's help does not need our strength; the city watched from the hills.",
    "Safety and food are blessings with a bill attached, and the bill is worship. Surah Quraysh says so.",
    "A year named for an elephant became the year a Prophet was born. Allah's dates are not ours." ] },
  { h: "Talk about it", l: [
    "Why did Abd al-Muttalib ask only for his camels and not for the House?",
    "What does Surah Quraysh ask in return for safety and food?",
    "What is something we are safe from that we never thank Allah for?" ] } ],
  kids: [ "Long ago, in the year the Prophet Muhammad ﷺ was born, a king called Abraha came with a huge army and a giant elephant to knock down the Ka'bah in Makkah.",
    "The people of Makkah could not fight such a big army. The Prophet's grandfather said: the Ka'bah has a Lord who will protect it. And the people went up into the hills.",
    "Allah sent flocks of little birds carrying tiny stones. They dropped them on the army, and the whole army was finished, like chewed-up straw. The elephant would not even walk toward the Ka'bah. Allah protected His House without anyone fighting at all." ] },
};
